// NewRouter wires the public HTTP surface. The error contract in README.md applies to every entry.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

